"use strict";function openBounceModal(a,t){var i=openModal(modalShell({icon:"fa-solid fa-arrow-rotate-left",iconClass:"danger",kicker:TKA.t("kicker_mail_bounce","Correo \xB7 rebote"),title:TKA.t("modal_title_bounced_email","Email rebotado"),titleChip:a.ticket_number,width:"md",body:'<div class="tkt-headline bad"><div class="t mono">'+escapeHtml(t.delivery_error||TKA.t("modal_06_bounce_no_detail","Rebote sin detalle del servidor"))+'</div><div class="s">'+TKA.t("modal_06_send_failed_to","El env\xEDo a :to no lleg\xF3 a su destino.",{":to":"<strong>"+escapeHtml(t.to||"\u2014")+"</strong>"})+'</div></div><div class="tkt-side-rows">'+sideRow(TKA.t("modal_06_subject_label","Asunto"),t.subject||"\u2014")+sideRow(TKA.t("status","Estado"),t.status||"\u2014",{mono:!0,last:!0})+'</div><div class="tkt-field"><label class="tkt-label" for="tkt-bounce-to">'+TKA.t("modal_06_fix_recipient_label","Corregir destinatario")+'<span class="req">*</span></label><input type="email" class="tkt-input" id="tkt-bounce-to" value="'+escapeHtml(t.to||"")+'"></div><label class="tkt-check"><input type="checkbox" id="tkt-bounce-contact" checked> '+TKA.t("modal_06_update_contact_email","Actualizar el email del contacto")+'</label><label class="tkt-check"><input type="checkbox" id="tkt-bounce-suppress" checked> '+TKA.t("modal_06_add_to_suppression_list","A\xF1adir la direcci\xF3n anterior a la lista de supresi\xF3n")+'</label><div class="tkt-note"><i class="fa-solid fa-circle-info"></i> '+TKA.t("modal_06_internal_note_notice","Se dejar\xE1 una nota interna en el ticket con el cambio de destinatario.")+"</div>",foot:'<button type="button" class="tkt-btn tkt-btn-primary" id="tkt-bounce-confirm">'+TKA.t("btn_fix_and_resend","Corregir y reenviar")+'</button><button type="button" class="tkt-btn" data-modal-close>'+TKA.t("discard","Descartar")+"</button>"}));i.on("click","#tkt-bounce-confirm",function(){var o=($("#tkt-bounce-to").val()||"").trim();if(!o){window.toastr&&toastr.error(TKA.t("corrected_recipient_required","Indica el destinatario corregido"));return}if(o===t.to){window.toastr&&toastr.error(TKA.t("recipient_same_as_bounced","El destinatario es el mismo que rebot\xF3: corr\xEDgelo antes de reenviar"));return}var r=$(this).prop("disabled",!0).text(TKA.t("btn_resending","Reenviando\u2026"));$.ajax({url:t.url_fix_bounce,method:"POST",data:{to:o,update_contact:$("#tkt-bounce-contact").is(":checked")?1:0,suppress_old:$("#tkt-bounce-suppress").is(":checked")?1:0},headers:{Accept:"application/json"},success:function(e){window.toastr&&toastr.success(e&&e.message||TKA.t("recipient_fixed_and_resent","Destinatario corregido y correo reenviado")),closeModal(),fetchDetailData(a)},error:function(e){var s=apiErrorMessage(e,"No se pudo corregir el rebote");tktNotify("error",s),r.prop("disabled",!1).text(TKA.t("btn_fix_and_resend","Corregir y reenviar"))}})})}
